import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  Inject,
  OnInit,
  Renderer2,
  ViewChild
} from '@angular/core';
import { DOCUMENT } from '@angular/common';
import { NgForm } from '@angular/forms';
import { Router } from '@angular/router';
import { of } from 'rxjs';
import { catchError, finalize, takeUntil } from 'rxjs/operators';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { BroadcastingService, roundNumber, TaxesService } from '@honoregaming/core';
import { AuthService, CustomerService, TelemetryService } from '@honoregaming/customer-core';
import { I18nService } from '@honoregaming/i18n';
import { ContentService } from '@honoregaming/templating';
import { SecurityPolicy } from '@honoregaming/types';
import { MessageService } from '@honoregaming/ui';
import { AccountService } from 'projects/customer/hg-account/src/lib/services/account.service';
import { WithdrawProvider } from 'projects/customer/hg-account/src/lib/models/withdraw-provider.model';
import { TransactionPopupService } from 'projects/customer/hg-core/src/lib/services/transaction-popup.service';
import {
  GenericTransactionResponse,
  PaymentProviderValidationType
} from '../../models/generic-transaction-response.model';
import { CustomerWithdrawalInformations } from '../../models/customer-withdrawal-informations.model';
import { WithdrawProviderBaseComponent } from '../../provider-base';

interface ProviderContent {
  content: string;
  title: string;
  style: string;
}

@Component({
  selector: 'hg-withdraw-provider',
  templateUrl: './withdraw-provider.component.html',
  styleUrls: ['./withdraw-provider.component.scss', '../../provider-base/provider-base.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class WithdrawProviderComponent extends WithdrawProviderBaseComponent implements OnInit, WithdrawProvider {
  @ViewChild('withdrawalForm') withdrawalForm?: NgForm;

  canUseDifferentAccount: boolean = false;
  useDifferentAccount: boolean = false;
  withdrawAccountNumber?: string;
  customerPassword?: string;
  displayPasswordModal: boolean = false;
  loadingPasswordSubmit: boolean = false;
  passwordFailure: boolean = false;

  securityPolicy?: SecurityPolicy;
  content?: ProviderContent;

  constructor(
    protected readonly authService: AuthService,
    protected readonly accountService: AccountService,
    private readonly customerService: CustomerService,
    protected readonly i18nService: I18nService,
    protected readonly renderer: Renderer2,
    protected readonly cdRef: ChangeDetectorRef,
    protected readonly bcService: BroadcastingService,
    private readonly contentService: ContentService,
    protected readonly taxesService: TaxesService,
    protected readonly messageService: MessageService,
    private readonly telemetryService: TelemetryService,
    protected readonly router: Router,
    protected readonly transactionPopupService: TransactionPopupService,
    @Inject(DOCUMENT) private readonly document: Document,
    @Inject(operatorConfigurationToken) protected readonly operatorConfiguration: OperatorConfiguration
  ) {
    super(
      taxesService,
      messageService,
      i18nService,
      operatorConfiguration,
      renderer,
      cdRef,
      bcService,
      router,
      transactionPopupService,
      accountService
    );
  }

  ngOnInit(): void {
    super.ngOnInit();

    this.canUseDifferentAccount = this.provider.canUseDifferentAccount;
    this.loadSecurityPolicy();
    this.loadContent();
  }

  get canSubmit(): boolean {
    const accountNumberInvalid: boolean =
      this.useDifferentAccount && !!this.withdrawalForm?.controls['accountNumber']?.errors;

    return this.isValid && !this.loading && !accountNumberInvalid;
  }

  checkValidity(value: number): void {
    super.checkValidity(value);

    if (this.useDifferentAccount && !this.withdrawAccountNumber) {
      this.isValid = false;
    }
  }

  submitWithdraw(): void {
    this.loading = true;
    this.failure = null;

    if (this.canUseDifferentAccount && this.useDifferentAccount && !!this.withdrawAccountNumber) {
      this.displayPasswordModal = true;
    } else {
      this.createWithdrawal(null);
    }
  }

  submitWithdrawWithPasswordConfirmation(): void {
    this.loadingPasswordSubmit = true;
    this.passwordFailure = false;
    this.authService
      .checkPassword(this.customerPassword)
      .pipe(
        finalize(() => {
          this.loadingPasswordSubmit = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        (isValidPassword: boolean) => {
          if (!isValidPassword) {
            this.passwordFailure = true;
            return;
          }

          this.closeDisplayPasswordModal(this.loading);

          this.createWithdrawal({
            useDifferentAccount: true,
            account: this.withdrawAccountNumber
          } as CustomerWithdrawalInformations);
        },
        () => {
          this.passwordFailure = true;
        }
      );
  }

  closeDisplayPasswordModal(loading: boolean): void {
    this.displayPasswordModal = false;
    this.loadingPasswordSubmit = false;
    this.passwordFailure = false;
    this.loading = loading;
  }

  private createWithdrawal(withdrawInfos?: CustomerWithdrawalInformations): void {
    this.accountService
      .createWithdraw(
        this.provider,
        roundNumber(this.amount, this.numberOfDecimals),
        this.selectedInnerProvider,
        this.customerPassword,
        withdrawInfos ?? ({} as CustomerWithdrawalInformations)
      )
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.customerPassword = null;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        (response: GenericTransactionResponse) => {
          if (PaymentProviderValidationType[response.validationType] === PaymentProviderValidationType.Redirection) {
            this.document.location.href = response.value;
          } else {
            this.step = PaymentProviderValidationType[response.validationType];
            this.submitted = true;
            this.bcService.broadcast('payment-provider-scroll-to-top');
            this.withdrawSuccess.emit();
          }

          this.telemetryService.trackEvent('withdrawal_validation_click', {
            provider_name: this.provider.displayName ?? this.provider.providerName,
            amount: this.amount
          });
        },
        (error: unknown) => {
          this.handleWithdrawError(error);
        }
      );
  }

  private loadSecurityPolicy(): void {
    this.customerService
      .getSecurityPolicy()
      .pipe(takeUntil(this.destroy$))
      .subscribe(policy => {
        this.securityPolicy = policy;
        this.cdRef.markForCheck();
      });
  }

  private loadContent(): void {
    this.contentService
      .getContent(`withdraw-provider-${this.provider.providerName.toLowerCase()}`)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        }),
        catchError(() => of(null))
      )
      .subscribe((content: ProviderContent | null) => {
        if (content) {
          this.content = content;
        }
      });
  }
}
