import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { finalize, catchError, takeUntil } from 'rxjs/operators';
import { of } from 'rxjs';
import { ContentService } from '@honoregaming/templating';
import { Provider } from 'projects/customer/hg-account/src/lib/models/provider.model';
import { Async, AsyncTrigger, DestroySubject } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';

@Component({
  selector: 'hg-deposit-provider-partner',
  templateUrl: './deposit-provider-partner.component.html',
  styleUrls: ['./deposit-provider-partner.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DepositProviderPartnerComponent extends DestroySubject implements OnInit {
  provider: Provider;
  uniqueProvider: boolean;
  content: { content: string; title: string; style: string };
  isLoading: boolean;

  @AsyncTrigger()
  languageTrigger = this.i18nService.languageChanged$;

  constructor(
    private cdRef: ChangeDetectorRef,
    private contentService: ContentService,
    private i18nService: I18nService
  ) {
    super();
  }

  ngOnInit() {
    this.load();
  }

  @Async()
  load(): void {
    this.isLoading = true;
    this.contentService
      .getContent(
        'deposit-partner-content-' + (this.provider.parentProviderName ?? this.provider.providerName).toLowerCase()
      )
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.isLoading = false;
          this.cdRef.markForCheck();
        }),
        catchError(_ => of(null))
      )
      .subscribe((content: { content: string; title: string; style: string }) => {
        this.content = content;
      });
  }
}
