import { Component, OnInit, ChangeDetectionStrategy, Renderer2, Inject, ChangeDetectorRef } from '@angular/core';
import { DOCUMENT } from '@angular/common';
import { Router } from '@angular/router';
import { of } from 'rxjs';
import { catchError, finalize, take, takeUntil } from 'rxjs/operators';
import { InAppBrowser, InAppBrowserObject } from '@ionic-native/in-app-browser/ngx';
import { Plugins } from '@capacitor/core';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { roundNumber, BroadcastingService, PaymentFailure, TaxesService } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { ContentService } from '@honoregaming/templating';
import { MessageService } from '@honoregaming/ui';
import { environment } from 'projects/customer/customer/src/environments/environment';
import { AccountService } from 'projects/customer/hg-account/src/lib/services/account.service';
import { DepositProvider } from 'projects/customer/hg-account/src/lib/models/deposit-provider.model';
import { OperationType } from 'projects/customer/hg-account/src/lib/models/operation.model';
import { TransactionPopupService } from 'projects/customer/hg-core/src/lib/services/transaction-popup.service';
import {
  GenericTransactionResponse,
  PaymentProviderValidationType
} from '../../models/generic-transaction-response.model';
import { getPaymentFailure } from '../../helpers/generic-payment-utils.helper';
import { OperationConfirmationType } from '../../enums/operation-confirmation-type.enum';
import { DepositProviderBaseComponent } from '../../provider-base';

interface QrCodeLink {
  name: string;
  value: string;
}

interface ProviderContent {
  content: string;
  title: string;
  style: string;
}

interface FormRedirectionContent {
  URL: string;
  [key: string]: string;
}

@Component({
  selector: 'hg-deposit-provider',
  templateUrl: './deposit-provider.component.html',
  styleUrls: ['./deposit-provider.component.scss', '../../provider-base/provider-base.component.scss'],
  providers: [InAppBrowser],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DepositProviderComponent extends DepositProviderBaseComponent implements OnInit, DepositProvider {
  balance?: number;
  otp: string | null = null;
  validationCode?: string;
  qrCodeValue: string | null = null;
  qrCodeUrls: QrCodeLink[] | null = null;
  operationRef: string | null = null;
  content?: ProviderContent;
  customerFirstName?: string;
  customerLastName?: string;

  otpPlaceholderKey!: string;
  customerFirstNamePlaceholderKey!: string;
  customerLastNamePlaceholderKey!: string;

  OperationType = OperationType;

  constructor(
    protected readonly accountService: AccountService,
    protected readonly i18nService: I18nService,
    protected readonly renderer: Renderer2,
    protected readonly cdRef: ChangeDetectorRef,
    protected readonly bcService: BroadcastingService,
    protected readonly router: Router,
    private readonly appBrowser: InAppBrowser,
    private readonly contentService: ContentService,
    protected readonly taxesService: TaxesService,
    protected readonly messageService: MessageService,
    protected readonly transactionPopupService: TransactionPopupService,

    @Inject(DOCUMENT) private readonly document: Document,
    @Inject(operatorConfigurationToken) protected readonly operatorConfiguration: OperatorConfiguration
  ) {
    super(
      taxesService,
      messageService,
      i18nService,
      operatorConfiguration,
      renderer,
      cdRef,
      bcService,
      router,
      transactionPopupService,
      accountService
    );
  }

  ngOnInit(): void {
    super.ngOnInit();
    this.otpPlaceholderKey = this.resolveTranslationKey('OTP', 'OTP');
    this.customerFirstNamePlaceholderKey = this.resolveTranslationKey('FIRSTNAME', 'FIRSTNAME');
    this.customerLastNamePlaceholderKey = this.resolveTranslationKey('LASTNAME', 'LASTNAME');

    this.contentService
      .getContent(`deposit-provider-${this.provider.providerName.toLowerCase()}`)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.step = 1;
          this.cdRef.markForCheck();
        }),
        catchError(() => of(null))
      )
      .subscribe((content: ProviderContent | null) => {
        if (content) {
          this.content = content;
        }
      });
  }

  get canSubmit(): boolean {
    return (
      this.isValid &&
      !this.loading &&
      (!this.provider.canUseOtpValidation || this.checkOtpValidity(this.otp)) &&
      (!this.provider.needCustomerFirstName || !!this.customerFirstName) &&
      (!this.provider.needCustomerLastName || !!this.customerLastName)
    );
  }

  submitDeposit(): void {
    if (!this.amount) {
      this.failure = getPaymentFailure(PaymentFailure.InsufficientAmount);
      return;
    }

    if (!this.isDepositFormComplete()) {
      return;
    }

    this.loading = true;
    this.failure = null;

    this.accountService
      .createDeposit(
        this.provider,
        roundNumber(this.amount, this.numberOfDecimals),
        this.otp,
        this.selectedInnerProvider,
        {
          firstName: this.customerFirstName,
          lastName: this.customerLastName
        }
      )
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        (response: GenericTransactionResponse) => {
          this.operationRef = response.operationRef;
          this.handleDepositResponse(response);
        },
        (error: unknown) => {
          this.handleDepositError(error);
          this.loading = false;
        }
      );
  }

  submitDepositConfirmationOtp(): void {
    if (!this.otp || !this.operationRef) {
      return;
    }

    this.loading = true;
    this.failure = null;

    this.accountService
      .confirmDeposit(
        this.provider,
        this.operationRef,
        OperationConfirmationType.OTP,
        { code: this.otp },
        this.selectedInnerProvider
      )
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        (response: GenericTransactionResponse) => {
          this.handleDepositResponse(response);
        },
        (error: unknown) => {
          this.handleDepositError(error);
          this.resetAfterConfirmationError();
        }
      );
  }

  private checkOtpValidity(value: string): boolean {
    const newValue: number = +(value != null ? this.i18nService.unformatNumber('' + value) : value);
    return !Number.isNaN(newValue);
  }

  private isDepositFormComplete(): boolean {
    if (this.provider.canUseOtpValidation && !this.otp) {
      return false;
    }
    if (this.provider.needCustomerFirstName && !this.customerFirstName) {
      return false;
    }
    if (this.provider.needCustomerLastName && !this.customerLastName) {
      return false;
    }
    return true;
  }

  private handleDepositResponse(response: GenericTransactionResponse): void {
    const validationType: PaymentProviderValidationType = PaymentProviderValidationType[response.validationType];

    if (validationType === PaymentProviderValidationType.Redirection) {
      this.processRedirection(response.value);
      return;
    }

    if (validationType === PaymentProviderValidationType.FormRedirection) {
      this.processFormRedirection(response.value);
      return;
    }

    this.applyInlineResponse(response, validationType);
  }

  private processRedirection(url: string): void {
    if (environment.natif && !this.provider.useBrowserRedirection) {
      this.executeNativeRedirection(url);
    } else {
      this.document.location.href = url;
    }
  }

  private processFormRedirection(content: FormRedirectionContent): void {
    if (environment.natif && !this.provider.useBrowserRedirection) {
      this.executeNativeFormRedirection(content);
    } else {
      this.executeFormRedirection(content);
    }
  }

  private applyInlineResponse(
    response: GenericTransactionResponse,
    validationType: PaymentProviderValidationType
  ): void {
    this.step = PaymentProviderValidationType[response.validationType];
    this.validationCode = response.value;
    this.qrCodeValue = this.extractQrCodeValue(response, validationType);
    this.qrCodeUrls = this.extractQrCodeUrls(response, validationType);
    this.submitted = true;
    this.loading = false;
    this.bcService.broadcast('payment-provider-scroll-to-top');

    if (
      validationType === PaymentProviderValidationType.Done ||
      validationType === PaymentProviderValidationType.Code ||
      validationType === PaymentProviderValidationType.Instructions
    ) {
      this.depositSuccess.emit();
    }
  }

  private extractQrCodeValue(
    response: GenericTransactionResponse,
    validationType: PaymentProviderValidationType
  ): string | null {
    if (validationType !== PaymentProviderValidationType.QrCode) {
      return null;
    }
    return 'data:image/png;base64,' + response.value['QrCodeBase64'];
  }

  private extractQrCodeUrls(
    response: GenericTransactionResponse,
    validationType: PaymentProviderValidationType
  ): QrCodeLink[] | null {
    if (validationType !== PaymentProviderValidationType.QrCode) {
      return null;
    }

    const links: { Name: string; Value: string }[] | undefined = response.value['Links'];
    return links?.map(link => ({ name: link.Name, value: link.Value })) ?? null;
  }

  private executeNativeRedirection(url: string): void {
    const { App } = Plugins;
    App.openUrl({ url });
    return;
  }

  private executeNativeFormRedirection(content: FormRedirectionContent): void {
    const browser: InAppBrowserObject = this.appBrowser.create('about:blank', '_blank', { zoom: 'no' });
    const script: string = `var executeFormRedirection = ${
      this.executeFormRedirection
    }; executeFormRedirection(${JSON.stringify(content)});`;

    browser
      .on('loadstop')
      .pipe(take(1))
      .subscribe(() => browser.executeScript({ code: script }));

    this.listenToRedirections(browser);
  }

  private listenToRedirections(browser: InAppBrowserObject): void {
    browser
      .on('loadstart')
      .pipe(takeUntil(this.destroy$))
      .subscribe((event: { url: string }) => {
        this.handleBrowserRedirect(browser, event.url);
      });
  }

  private handleBrowserRedirect(browser: InAppBrowserObject, url: string): void {
    const redirectionMatch: RegExpMatchArray | null = new RegExp(/\/redirection\/(.*)/).exec(url);
    const myAccountMatch: RegExpMatchArray | null = new RegExp(/\/myaccount\/(.*)/).exec(url);

    if (redirectionMatch) {
      browser.close();
      this.router.navigate(['myaccount', redirectionMatch[1]]);
      return;
    }

    if (myAccountMatch) {
      browser.close();
      this.router.navigate(['myaccount', myAccountMatch[1]]);
    }
  }

  private executeFormRedirection(content: FormRedirectionContent): void {
    const form: HTMLFormElement = document.createElement('form');
    form.method = 'POST';
    form.action = content['URL'];

    for (const property of Object.keys(content)) {
      if (property === 'URL') {
        continue;
      }

      const hiddenField: HTMLInputElement = document.createElement('input');
      hiddenField.type = 'hidden';
      hiddenField.name = property;
      hiddenField.value = content[property];
      form.appendChild(hiddenField);
    }

    document.body.appendChild(form);
    form.submit();
  }

  private resetAfterConfirmationError(): void {
    this.loading = false;
    this.step = 1;
    this.otp = null;
    this.operationRef = null;
    this.qrCodeUrls = null;
    this.qrCodeValue = null;
  }
}
